// PHASE 1 — Type Definitions
// ═══════════════════════════════════════

export interface CoreValue {
  icon: string;
  title: string;
  description: string;
}

export interface AboutTimelineItem {
  year: number;
  title: string;
  description: string;
}

export interface HistoryEntry {
  id: string;
  year: number;
  decade: "1990s" | "2000s" | "2010s" | "2020s";
  title: string;
  description: string;
  imageUrl: string;
  relatedPeople: string[];
  tournament?: string;
}

export type HallOfFameCategory =
  | "Sáng lập"
  | "Ban quản lý"
  | "Đội trưởng"
  | "Đội phó"
  | "Cầu thủ nổi bật"
  | "Kỷ lục"
  | "Khoảnh khắc"
  | "Nhà tài trợ";

export interface HallOfFameEntry {
  id: string;
  name: string;
  categories: HallOfFameCategory[];
  title: string;
  year: number | string;
  description: string;
  avatarUrl: string;
  highlight?: boolean;
}

export interface FullHistoryItem {
  year: number;
  type: "founding" | "achievement" | "president";
  title: string;
  subtitle: string;
  description: string;
}

