// ═══════════════════════════════════════
// TASK-007 — Type Definitions
// ═══════════════════════════════════════

export interface MatchPlayer {
  name: string;
  number: number;
  position: string;
}

export interface MatchGoal {
  player: string;
  minute: number;
  assist?: string;
  side: "GODA" | "opponent";
}

export interface MatchCard {
  player: string;
  minute: number;
  type: "yellow" | "red";
  side: "GODA" | "opponent";
}

export interface MatchResult {
  id: string;
  season: string;
  date: string;
  time?: string;
  venue: string;
  type: "Giao hữu" | "Giải đấu" | "Cúp" | "Sự kiện";
  tournament?: string;
  isHome: boolean;
  opponent: string;
  homeTeam?: string;
  awayTeam?: string;
  opponentScore: number;
  godaScore: number;
  godaLineup: MatchPlayer[];
  opponentLineup: MatchPlayer[];
  goals: MatchGoal[];
  cards: MatchCard[];
  mvp?: string;
  imageUrl: string;
  videoUrl?: string;
  googleMapsUrl?: string;
  godaJerseyColor?: string;
  opponentJerseyColor?: string;
  postponed?: boolean;
  postponedReason?: string;
  eventTitle?: string;
  eventDescription?: string;
}

// Trận có GODA tham gia (không phải sự kiện, không phải trận giữa các đội khác)
export function isGodaMatch(m: MatchResult): boolean {
  if (m.type === "Sự kiện") return false;
  if (m.homeTeam && m.awayTeam) {
    return m.homeTeam.includes("GODA") || m.awayTeam.includes("GODA");
  }
  return true;
}

