export type MemberPosition = "Thủ môn" | "Hậu vệ" | "Tiền vệ" | "Tiền đạo";

export interface MemberPublic {
  id: string;
  name: string;
  nickname: string;
  position: MemberPosition;
  number: number;
  avatarUrl: string;
  matches: number;
  goals: number;
  assists: number;
  mvp: number;
  birthday?: string;
  joinYear?: number;
  joinDate?: string;
  status?: string;
}

export type AlbumCategory = "Trận đấu" | "Sự kiện" | "Sinh hoạt" | "Kỷ niệm" | "Video";

export interface AlbumPhoto {
  id: string;
  category: AlbumCategory;
  title: string;
  date: string;
  thumbnailUrl: string;
  fullUrl: string;
  videoUrl?: string;
}

